import { format } from 'prettier';
import { readdir, writeFile } from 'node:fs/promises';
const directories = (await readdir('src/lib/puzzles', { withFileTypes: true }))
	.filter((entry) => entry.isDirectory())
	.map((entry) => entry.name)
	.sort();
const lines = [
	'// Generated by scripts/generate-registry.ts. Do not edit by hand.',
	"import type { PuzzleId, PuzzleManifest } from './engine/contract.js';"
];
for (const [index, directory] of directories.entries()) {
	lines.push(`import { manifest as manifest${index} } from './puzzles/${directory}/manifest.js';`);
}
lines.push(
	`export const catalog: Record<PuzzleId, PuzzleManifest> = Object.fromEntries([${directories.map((_, i) => `manifest${i}`).join(',')}].map((manifest) => [manifest.id, manifest])) as Record<PuzzleId, PuzzleManifest>;`
);
lines.push(
	"export { createBlockRound, replayBlockMoves, BLOCK_SO_CLOSE_GAP } from './puzzles/block-placement/logic.js';",
	"export type { BlockRound, BlockEndReason } from './puzzles/block-placement/logic.js';",
	"export { createMemoryRound } from './puzzles/memory/logic.js';",
	"export type { MemoryRound } from './puzzles/memory/logic.js';",
	"export { default as BlockGame } from './puzzles/block-placement/Game.svelte';",
	"export { default as MemoryGame } from './puzzles/memory/Game.svelte';"
);
await writeFile(
	'src/lib/registry.ts',
	await format(lines.join('\n'), {
		parser: 'typescript',
		useTabs: true,
		singleQuote: true,
		trailingComma: 'none',
		printWidth: 100
	})
);
// Headless consumers must never load a Svelte view.
await writeFile(
	'src/lib/catalog.ts',
	await format(lines.filter((line) => !line.includes('.svelte')).join('\n'), {
		parser: 'typescript',
		useTabs: true,
		singleQuote: true,
		trailingComma: 'none',
		printWidth: 100
	})
);
